insert into public.categories (slug, title, display_title, description, image_url, scene, sort_order) values
  ('tour-from-dhaka', 'Tour from Dhaka', 'DHAKA', 'Weekend escapes and long trips departing every week from Dhaka to the hills, sea and forests.', null, 'city', 1),
  ('tour-from-chattogram', 'Tour from Chattogram', 'CHATTOGRAM', 'Hill tracts, waterfalls and island hops starting right from the port city.', null, 'waterfall', 2),
  ('tour-from-sylhet', 'Tour from Sylhet', 'SYLHET', 'Tea gardens, swamp forests, haors and crystal rivers of the north-east.', null, 'tea', 3),
  ('domestic-trips', 'Domestic Trips', 'DOMESTIC TRIPS', 'Thoughtfully planned trips covering the most scenic destinations of Bangladesh.', null, 'beach', 4),
  ('customized-tours', 'Customized Tours', 'CUSTOMIZED TOUR', 'Personalized travel experiences tailored to your destination, budget and interests.', null, 'lake', 5),
  ('campus-tour', 'Campus Tour', 'CAMPUS', 'Educational trips and student group tours designed with safe travel in mind.', null, 'heritage', 6),
  ('heritage-tour', 'Heritage Tour', 'HERITAGE TOUR', 'Ancient mosques, temples and ruins — Bagerhat, Paharpur, Mahasthangarh and Sonargaon.', null, 'heritage', 7),
  ('family-tour', 'Family Tour', 'FAMILY TOUR', 'Unforgettable family memories with comfortable stays, easy pace and kid-friendly plans.', null, 'island', 8),
  ('adventure-trek', 'Adventure Trek', 'TREKKING', 'Multi-day treks to Keokradong, Amiakhum, Nafakhum and the hidden falls of Bandarban.', null, 'hills', 9),
  ('corporate-tour', 'Corporate Tour', 'CORPORATE TOUR', 'Team outings, retreats and offsites with end-to-end logistics handled for you.', null, 'forest', 10),
  ('honeymoon-tours', 'Honeymoon Tours', 'HONEYMOON TOUR', 'Private resorts, sunset beaches and quiet hill cottages for couples.', null, 'beach', 11);
insert into public.packages (slug, title, tagline, category_slug, region, level, duration_days, duration_nights, altitude, age_group, gender, price, original_price, short_description, overview, highlights, images, scene, inclusions, exclusions, things_to_carry, itinerary, pickup_points, faqs, policies, map_query, featured, sort_order) values
  ('sajek-valley-tour', 'Sajek Valley Tour', 'Walk above the clouds.', 'tour-from-dhaka', 'Rangamati', 'Beginner', 2, 1, '1,800 ft', 'Open for all', 'Both', 5499, 6500, 'Sajek Valley is the “Queen of Hills” of Bangladesh — a ridge-top village floating above a sea of clouds, famous for sunrise views from Konglak Para.', '["Sajek Valley sits on the border of Rangamati and Mizoram at around 1,800 ft. In the early morning the valley below fills with clouds, so it feels like you are standing on an island in the sky.","This weekend tour departs Friday night from Dhaka, goes through Khagrachari by Chander Gari (jeep), and covers Konglak Para, Helipad sunset, Ruilui Para and Hazachora waterfall on the way back."]'::jsonb, '["Sunrise above the clouds from Konglak hill","Chander Gari ride through the hill roads","Sunset at Sajek Helipad","Hazachora waterfall & Alutila cave on return","Cottage stay with valley view"]'::jsonb, '[]'::jsonb, 'hills', '["AC bus Dhaka – Khagrachari – Dhaka","Chander Gari (jeep) for all transfers","1 night cottage stay (4 per room)","4 meals (lunch, BBQ dinner, breakfast, lunch)","Army escort & entry fees","Experienced trip leader & first aid"]'::jsonb, '["Personal expenses","Snacks & drinks","Anything not mentioned in inclusions"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":0,"title":"Departure from Dhaka","items":[{"time":"09:30 PM","text":"Pickup from Arambagh"},{"time":"09:45 PM","text":"Pickup from Kalabagan"},{"time":"10:30 PM","text":"Overnight AC bus to Khagrachari"}],"stay":"Bus","duration":"8h"},{"day":1,"title":"Khagrachari to Sajek","items":[{"time":"07:00 AM","text":"Reach Khagrachari, fresh up & breakfast"},{"time":"10:00 AM","text":"Chander Gari with army escort to Sajek"},{"time":"01:30 PM","text":"Check-in to cottage & lunch"},{"time":"04:00 PM","text":"Ruilui Para walk & sunset at Helipad"},{"time":"08:00 PM","text":"BBQ dinner under the stars"}],"meals":"Lunch, Dinner","stay":"Cottage","duration":"12h"},{"day":2,"title":"Konglak sunrise & return","items":[{"time":"05:15 AM","text":"Short hike to Konglak Para for sunrise over clouds"},{"time":"08:30 AM","text":"Breakfast & check-out"},{"time":"11:30 AM","text":"Hazachora waterfall & Alutila cave"},{"time":"09:00 PM","text":"Night bus back to Dhaka"}],"meals":"Breakfast, Lunch","stay":"Bus","duration":"16h"}]'::jsonb, '[{"id":"dhaka-arambagh","name":"Arambagh Bus Counter","detail":"Motijheel, Dhaka","time":"09:30 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Arambagh+Bus+Counter+Dhaka"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"09:45 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"},{"id":"dhaka-sayedabad","name":"Sayedabad Bus Terminal","detail":"Jatrabari, Dhaka","time":"10:15 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Sayedabad+Bus+Terminal"},{"id":"base-assembly","name":"Base Assembly Point","detail":"Join directly at the starting point (self travel)","time":"As per itinerary","extraFee":-500}]'::jsonb, '[{"question":"When is the best time to visit Sajek?","answer":"Monsoon (June–September) for the sea of clouds, and winter (November–February) for clear skies."},{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous trekking experience?","answer":"Not for beginner-level trips. For moderate and challenging trips, basic fitness and a few practice walks are recommended."},{"question":"Is food included?","answer":"Yes, meals listed in the itinerary are included. Please tell us about dietary needs while booking."},{"question":"Can girls / solo travellers join?","answer":"Absolutely. Our groups are mixed and every trip has trained leaders. Female travellers get separate room or tent arrangements."}]'::jsonb, '[{"title":"Booking & Payment","body":"Submitting the booking form reserves your seats. Our team calls you within 24 hours to confirm and share payment instructions (bKash / Nagad / bank transfer). Seats are held for 48 hours."},{"title":"Cancellation","body":"Cancel 15+ days before departure: full refund minus ৳500 processing fee. 7–14 days: 50% refund. Less than 7 days: no refund, but you may transfer your seat to a friend."},{"title":"Weather & Safety","body":"Routes can change due to weather, government advisories or safety concerns. The trip leader’s decision on the trail is final. Alternative plans are provided at no extra cost."},{"title":"Code of Conduct","body":"Respect local communities and nature. No littering, no loud music in villages, and alcohol or drugs are strictly prohibited during the trip."}]'::jsonb, 'Sajek Valley, Rangamati', true, 1),
  ('saint-martin-island-tour', 'Saint Martin''s Island Tour', 'Coral island, endless blue.', 'domestic-trips', 'Cox''s Bazar', 'Beginner', 3, 2, 'Sea level', 'Open for all', 'Both', 8999, 10500, 'Bangladesh''s only coral island — turquoise water, coconut groves, Chhera Dwip at low tide and the best sunsets on the Bay of Bengal.', '["Saint Martin''s Island lies 9 km south of the Teknaf peninsula. Its clear water, coral stones and laid-back village life make it the most loved beach destination in the country.","We take the ship from Cox’s Bazar / Teknaf, stay two nights in a beach resort, cycle around the island and walk to Chhera Dwip during low tide."]'::jsonb, '["Ship cruise on the Bay of Bengal","Chhera Dwip low-tide walk","Sea-facing resort","Fresh seafood BBQ","Island cycling"]'::jsonb, '[]'::jsonb, 'island', '["AC bus Dhaka – Cox’s Bazar – Dhaka","Ship tickets (both ways)","2 nights resort stay","All meals on the island","Seafood BBQ night","Trip leader & first aid"]'::jsonb, '["Bicycle / van rent","Personal expenses","Water sports"]'::jsonb, '["Backpack (30–40 L)","Flip-flops & swimwear","Extra clothes","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Dhaka to Cox’s Bazar & ship","items":[{"time":"07:00 AM","text":"Reach Cox’s Bazar, breakfast"},{"time":"09:30 AM","text":"Board the ship to Saint Martin"},{"time":"02:00 PM","text":"Check-in & lunch"},{"time":"05:30 PM","text":"Sunset at west beach"}],"meals":"Breakfast, Lunch, Dinner","stay":"Resort","duration":"14h"},{"day":2,"title":"Chhera Dwip & island day","items":[{"time":"07:00 AM","text":"Trawler / walk to Chhera Dwip"},{"time":"01:00 PM","text":"Lunch & rest"},{"time":"04:00 PM","text":"Cycling around the island"},{"time":"08:00 PM","text":"Seafood BBQ"}],"meals":"All meals","stay":"Resort","duration":"12h"},{"day":3,"title":"Return","items":[{"time":"09:00 AM","text":"Breakfast & free time"},{"time":"03:00 PM","text":"Ship back to the mainland"},{"time":"09:00 PM","text":"Night bus to Dhaka"}],"meals":"Breakfast, Lunch","stay":"Bus","duration":"14h"}]'::jsonb, '[{"id":"dhaka-arambagh","name":"Arambagh Bus Counter","detail":"Motijheel, Dhaka","time":"09:30 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Arambagh+Bus+Counter+Dhaka"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"09:45 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"},{"id":"dhaka-sayedabad","name":"Sayedabad Bus Terminal","detail":"Jatrabari, Dhaka","time":"10:15 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Sayedabad+Bus+Terminal"},{"id":"base-assembly","name":"Base Assembly Point","detail":"Join directly at the starting point (self travel)","time":"As per itinerary","extraFee":-500}]'::jsonb, '[{"question":"When do ships run to Saint Martin?","answer":"Ships usually operate from November to March, subject to government permission and weather."},{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous trekking experience?","answer":"Not for beginner-level trips. For moderate and challenging trips, basic fitness and a few practice walks are recommended."},{"question":"Is food included?","answer":"Yes, meals listed in the itinerary are included. Please tell us about dietary needs while booking."},{"question":"Can girls / solo travellers join?","answer":"Absolutely. Our groups are mixed and every trip has trained leaders. Female travellers get separate room or tent arrangements."}]'::jsonb, '[{"title":"Booking & Payment","body":"Submitting the booking form reserves your seats. Our team calls you within 24 hours to confirm and share payment instructions (bKash / Nagad / bank transfer). Seats are held for 48 hours."},{"title":"Cancellation","body":"Cancel 15+ days before departure: full refund minus ৳500 processing fee. 7–14 days: 50% refund. Less than 7 days: no refund, but you may transfer your seat to a friend."},{"title":"Weather & Safety","body":"Routes can change due to weather, government advisories or safety concerns. The trip leader’s decision on the trail is final. Alternative plans are provided at no extra cost."},{"title":"Code of Conduct","body":"Respect local communities and nature. No littering, no loud music in villages, and alcohol or drugs are strictly prohibited during the trip."}]'::jsonb, 'Saint Martin''s Island, Bangladesh', true, 2),
  ('nafakhum-waterfall-trek', 'Nafakhum Waterfall Trek', 'The Niagara of Bangladesh.', 'adventure-trek', 'Bandarban', 'Moderate', 3, 2, '1,200 ft', '16 – 45 years', 'Both', 7499, 8500, 'Boat up the Sangu river to Remakri and trek through jungle trails to Nafakhum, the largest waterfall by volume in Bangladesh.', '["Nafakhum is a wide, roaring waterfall on the Remakri river deep inside Thanchi, Bandarban. Reaching it means an engine-boat ride on the Sangu, river-side trails and stream crossings.","We stay in a Marma village guest house at Remakri, swim in natural pools and return through Tindu and Raja Pathar."]'::jsonb, '["Sangu river boat journey","Remakri falls","Nafakhum waterfall","Village stay with Marma community","Raja Pathar stone field"]'::jsonb, '[]'::jsonb, 'waterfall', '["Bus Dhaka – Bandarban – Dhaka","Chander Gari to Thanchi","Engine boat Thanchi – Remakri","Local guide & permits","2 nights village guest house","All meals on trek"]'::jsonb, '["Life jacket rent (৳100)","Personal expenses","Porter charges"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Bandarban to Remakri","items":[{"time":"06:30 AM","text":"Reach Bandarban, breakfast"},{"time":"08:00 AM","text":"Chander Gari to Thanchi, guide entry at BGB camp"},{"time":"12:30 PM","text":"Boat ride on the Sangu to Remakri"},{"time":"05:00 PM","text":"Check-in to village guest house"}],"meals":"Breakfast, Lunch, Dinner","stay":"Guest house","duration":"11h"},{"day":2,"title":"Trek to Nafakhum","items":[{"time":"07:00 AM","text":"Trek along the Remakri stream (2.5 h)"},{"time":"10:00 AM","text":"Nafakhum waterfall — swim & explore"},{"time":"03:00 PM","text":"Return to Remakri"}],"meals":"All meals","stay":"Guest house","duration":"9h"},{"day":3,"title":"Return to Dhaka","items":[{"time":"07:00 AM","text":"Boat to Thanchi via Tindu & Raja Pathar"},{"time":"02:00 PM","text":"Chander Gari to Bandarban"},{"time":"10:00 PM","text":"Night bus to Dhaka"}],"meals":"Breakfast, Lunch","stay":"Bus","duration":"15h"}]'::jsonb, '[{"id":"dhaka-arambagh","name":"Arambagh Bus Counter","detail":"Motijheel, Dhaka","time":"09:30 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Arambagh+Bus+Counter+Dhaka"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"09:45 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"},{"id":"dhaka-sayedabad","name":"Sayedabad Bus Terminal","detail":"Jatrabari, Dhaka","time":"10:15 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Sayedabad+Bus+Terminal"},{"id":"base-assembly","name":"Base Assembly Point","detail":"Join directly at the starting point (self travel)","time":"As per itinerary","extraFee":-500}]'::jsonb, '[{"question":"How long is the walk to Nafakhum?","answer":"About 2–3 hours each way from Remakri on mostly flat river-side trails with a few stream crossings."},{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous trekking experience?","answer":"Not for beginner-level trips. For moderate and challenging trips, basic fitness and a few practice walks are recommended."},{"question":"Is food included?","answer":"Yes, meals listed in the itinerary are included. Please tell us about dietary needs while booking."},{"question":"Can girls / solo travellers join?","answer":"Absolutely. Our groups are mixed and every trip has trained leaders. Female travellers get separate room or tent arrangements."}]'::jsonb, '[{"title":"Booking & Payment","body":"Submitting the booking form reserves your seats. Our team calls you within 24 hours to confirm and share payment instructions (bKash / Nagad / bank transfer). Seats are held for 48 hours."},{"title":"Cancellation","body":"Cancel 15+ days before departure: full refund minus ৳500 processing fee. 7–14 days: 50% refund. Less than 7 days: no refund, but you may transfer your seat to a friend."},{"title":"Weather & Safety","body":"Routes can change due to weather, government advisories or safety concerns. The trip leader’s decision on the trail is final. Alternative plans are provided at no extra cost."},{"title":"Code of Conduct","body":"Respect local communities and nature. No littering, no loud music in villages, and alcohol or drugs are strictly prohibited during the trip."}]'::jsonb, 'Nafakhum Waterfall, Thanchi, Bandarban', true, 3),
  ('keokradong-summit-trek', 'Keokradong Summit Trek', 'One of the highest peaks of Bangladesh.', 'adventure-trek', 'Bandarban', 'Challenging', 4, 3, '3,172 ft', '18 – 45 years', 'Both', 6999, 8000, 'Trek from Ruma to Boga Lake and up to Keokradong summit, passing Darjeeling Para and Chingri waterfall on the way.', '["Keokradong is a classic multi-day trek in Ruma upazila of Bandarban. The trail climbs through Bawm villages, jhum fields and dense hill forest.","You will camp beside the mysterious crater lake of Boga Lake, wake up for sunrise on the summit, and come back through Chingri jhiri."]'::jsonb, '["Boga Lake night stay","Keokradong summit sunrise","Darjeeling Para village","Chingri waterfall","Bawm community food"]'::jsonb, '[]'::jsonb, 'hills', '["Bus Dhaka – Bandarban – Dhaka","Chander Gari to Ruma & Boga Lake","Registered guide & permits","3 nights village homestay","All meals on trek"]'::jsonb, '["Porter","Personal expenses"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Bandarban to Boga Lake","items":[{"time":"07:00 AM","text":"Reach Bandarban & breakfast"},{"time":"09:00 AM","text":"Chander Gari to Ruma, guide entry"},{"time":"03:00 PM","text":"Reach Boga Lake, swim & relax"}],"meals":"All meals","stay":"Homestay","duration":"10h"},{"day":2,"title":"Boga Lake to Keokradong","items":[{"time":"06:30 AM","text":"Start trek via Chingri waterfall"},{"time":"11:30 AM","text":"Darjeeling Para lunch"},{"time":"02:00 PM","text":"Reach Keokradong summit"}],"meals":"All meals","stay":"Summit homestay","duration":"8h"},{"day":3,"title":"Summit sunrise & descent","items":[{"time":"05:30 AM","text":"Sunrise from the summit"},{"time":"08:00 AM","text":"Descend to Boga Lake"},{"time":"04:00 PM","text":"Rest & bonfire"}],"meals":"All meals","stay":"Homestay","duration":"8h"},{"day":4,"title":"Return","items":[{"time":"07:00 AM","text":"Chander Gari back to Bandarban"},{"time":"10:00 PM","text":"Night bus to Dhaka"}],"meals":"Breakfast, Lunch","stay":"Bus","duration":"15h"}]'::jsonb, '[{"id":"dhaka-arambagh","name":"Arambagh Bus Counter","detail":"Motijheel, Dhaka","time":"09:30 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Arambagh+Bus+Counter+Dhaka"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"09:45 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"},{"id":"dhaka-sayedabad","name":"Sayedabad Bus Terminal","detail":"Jatrabari, Dhaka","time":"10:15 PM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Sayedabad+Bus+Terminal"},{"id":"base-assembly","name":"Base Assembly Point","detail":"Join directly at the starting point (self travel)","time":"As per itinerary","extraFee":-500}]'::jsonb, '[{"question":"How fit do I need to be?","answer":"You should be comfortable walking 6–7 hours a day on steep trails. Start walking or stair practice 2–3 weeks before."},{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous trekking experience?","answer":"Not for beginner-level trips. For moderate and challenging trips, basic fitness and a few practice walks are recommended."},{"question":"Is food included?","answer":"Yes, meals listed in the itinerary are included. Please tell us about dietary needs while booking."},{"question":"Can girls / solo travellers join?","answer":"Absolutely. Our groups are mixed and every trip has trained leaders. Female travellers get separate room or tent arrangements."}]'::jsonb, '[{"title":"Booking & Payment","body":"Submitting the booking form reserves your seats. Our team calls you within 24 hours to confirm and share payment instructions (bKash / Nagad / bank transfer). Seats are held for 48 hours."},{"title":"Cancellation","body":"Cancel 15+ days before departure: full refund minus ৳500 processing fee. 7–14 days: 50% refund. Less than 7 days: no refund, but you may transfer your seat to a friend."},{"title":"Weather & Safety","body":"Routes can change due to weather, government advisories or safety concerns. The trip leader’s decision on the trail is final. Alternative plans are provided at no extra cost."},{"title":"Code of Conduct","body":"Respect local communities and nature. No littering, no loud music in villages, and alcohol or drugs are strictly prohibited during the trip."}]'::jsonb, 'Keokradong, Ruma, Bandarban', true, 4),
  ('sundarbans-mangrove-safari', 'Sundarbans Mangrove Safari', 'Home of the Royal Bengal Tiger.', 'domestic-trips', 'Khulna', 'Beginner', 3, 2, 'Sea level', 'Open for all', 'Both', 11500, 13000, 'Cruise the world’s largest mangrove forest on a houseboat — Kotka, Kochikhali, Harbaria and Karamjal with forest guards.', '["The Sundarbans is a UNESCO World Heritage Site spread across the delta of the Padma, Meghna and Brahmaputra. This 3-day houseboat safari covers the most wildlife-rich zones.","Spot spotted deer, crocodiles, monkeys, kingfishers and, if you are lucky, tiger pugmarks along the forest trails."]'::jsonb, '["AC houseboat with cabins","Kotka beach & watch tower","Jamtola sea beach","Canal cruise by country boat","Wildlife spotting"]'::jsonb, '[]'::jsonb, 'mangrove', '["Houseboat cabin stay","All meals on board","Forest permits & armed guard","Country boat canal rides","Pickup from Khulna"]'::jsonb, '["Dhaka – Khulna transport","Personal expenses"]'::jsonb, '["Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses","Binoculars (optional)","Mosquito repellent"]'::jsonb, '[{"day":1,"title":"Khulna to Harbaria","items":[{"time":"07:00 AM","text":"Board the houseboat at Khulna"},{"time":"01:00 PM","text":"Harbaria eco trail"},{"time":"07:00 PM","text":"Anchor near Kotka"}],"meals":"All meals","stay":"Houseboat","duration":"12h"},{"day":2,"title":"Kotka & Kochikhali","items":[{"time":"06:00 AM","text":"Canal ride by country boat"},{"time":"09:00 AM","text":"Jamtola beach walk"},{"time":"03:00 PM","text":"Kochikhali grassland"}],"meals":"All meals","stay":"Houseboat","duration":"12h"},{"day":3,"title":"Karamjal & return","items":[{"time":"10:00 AM","text":"Karamjal crocodile breeding centre"},{"time":"05:00 PM","text":"Arrive Khulna"}],"meals":"Breakfast, Lunch","duration":"10h"}]'::jsonb, '[{"id":"khulna-launch","name":"Khulna Launch Ghat","detail":"Khulna City","time":"07:00 AM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Khulna+Launch+Ghat"},{"id":"dhaka-bus","name":"Dhaka (AC bus add-on)","detail":"Gabtoli, Dhaka — previous night","time":"10:00 PM","extraFee":2200}]'::jsonb, '[{"question":"Will we see a tiger?","answer":"Tiger sightings are rare. You will most likely see deer, monkeys, crocodiles and many birds."},{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous trekking experience?","answer":"Not for beginner-level trips. For moderate and challenging trips, basic fitness and a few practice walks are recommended."},{"question":"Is food included?","answer":"Yes, meals listed in the itinerary are included. Please tell us about dietary needs while booking."},{"question":"Can girls / solo travellers join?","answer":"Absolutely. Our groups are mixed and every trip has trained leaders. Female travellers get separate room or tent arrangements."}]'::jsonb, '[{"title":"Booking & Payment","body":"Submitting the booking form reserves your seats. Our team calls you within 24 hours to confirm and share payment instructions (bKash / Nagad / bank transfer). Seats are held for 48 hours."},{"title":"Cancellation","body":"Cancel 15+ days before departure: full refund minus ৳500 processing fee. 7–14 days: 50% refund. Less than 7 days: no refund, but you may transfer your seat to a friend."},{"title":"Weather & Safety","body":"Routes can change due to weather, government advisories or safety concerns. The trip leader’s decision on the trail is final. Alternative plans are provided at no extra cost."},{"title":"Code of Conduct","body":"Respect local communities and nature. No littering, no loud music in villages, and alcohol or drugs are strictly prohibited during the trip."}]'::jsonb, 'Sundarbans, Khulna', true, 5),
  ('sreemangal-tea-garden-tour', 'Sreemangal Tea Garden Tour', 'Tea capital of Bangladesh.', 'tour-from-sylhet', 'Moulvibazar', 'Beginner', 2, 1, '200 ft', 'Open for all', 'Both', 4999, 5800, 'Green tea estates, Lawachara rainforest, Madhabpur lake and the famous seven-layer tea of Sreemangal.', '["Sreemangal is covered with rolling tea gardens and is the gateway to Lawachara National Park, home to the hoolock gibbon.","Enjoy a jungle walk, visit Khasi villages, sip the seven-colour tea and relax at a resort among the tea bushes."]'::jsonb, '["Lawachara rainforest walk","Seven-layer tea","Madhabpur lake","Tea estate drive","Khasia village"]'::jsonb, '[]'::jsonb, 'tea', '["Train/bus tickets","Resort stay","4 meals","Local transport","Guide & entry fees"]'::jsonb, '["Personal expenses"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Arrive & explore","items":[{"time":"06:30 AM","text":"Reach Sreemangal, breakfast"},{"time":"09:00 AM","text":"Lawachara forest trail"},{"time":"03:00 PM","text":"Madhabpur lake & tea estate"}],"meals":"All meals","stay":"Resort","duration":"12h"},{"day":2,"title":"Tea & return","items":[{"time":"08:00 AM","text":"Tea factory & Baikka Beel"},{"time":"04:00 PM","text":"Seven-layer tea & return"}],"meals":"Breakfast, Lunch","duration":"12h"}]'::jsonb, '[{"id":"syl-ambarkhana","name":"Ambarkhana Point","detail":"Sylhet City","time":"07:30 AM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Ambarkhana+Sylhet"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"11:00 PM (previous night)","extraFee":1100,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"},{"id":"dhaka-arambagh","name":"Arambagh Bus Counter","detail":"Motijheel, Dha