  ('ratargul-bichanakandi-tour', 'Ratargul & Bichanakandi Tour', 'Swamp forest and stone rivers.', 'tour-from-sylhet', 'Sylhet', 'Beginner', 2, 1, null, 'Open for all', 'Both', 4499, 5200, 'Row through the flooded Ratargul swamp forest and soak in the crystal water of Bichanakandi under Meghalaya’s hills.', '["Ratargul is the only freshwater swamp forest of Bangladesh, best seen by small boat in the monsoon.","Bichanakandi is a stony river bed at the foot of the Khasi hills, with clear cold water flowing from Meghalaya."]'::jsonb, '["Boat ride in Ratargul","Bichanakandi stones","Jaflong view point","Sylhet city & shrine visit"]'::jsonb, '[]'::jsonb, 'forest', '["Transport from Sylhet","Hotel stay","Boats","4 meals","Guide"]'::jsonb, '["Personal expenses"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Ratargul","items":[{"time":"08:00 AM","text":"Drive to Ratargul"},{"time":"10:00 AM","text":"Boat ride in the swamp forest"},{"time":"04:00 PM","text":"Return to Sylhet"}],"meals":"All meals","stay":"Hotel","duration":"9h"},{"day":2,"title":"Bichanakandi","items":[{"time":"07:30 AM","text":"Drive to Hadarpar & boat to Bichanakandi"},{"time":"03:00 PM","text":"Return & departure"}],"meals":"Breakfast, Lunch","duration":"10h"}]'::jsonb, '[{"id":"syl-ambarkhana","name":"Ambarkhana Point","detail":"Sylhet City","time":"07:30 AM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Ambarkhana+Sylhet"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"11:00 PM (previous night)","extraFee":1100,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"}]'::jsonb, '[{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as liste