  ('tanguar-haor-houseboat', 'Tanguar Haor Houseboat', 'Sleep on the water.', 'tour-from-sylhet', 'Sunamganj', 'Beginner', 2, 1, null, 'Open for all', 'Both', 6500, 7200, 'A night on a wooden houseboat in Tanguar Haor with the Meghalaya hills, Niladri Lake and Barikka Tila.', '["Tanguar Haor is a vast wetland of Sunamganj. We spend a day and a night on a modern houseboat, swimming in the swamp forest and visiting Niladri Lake."]'::jsonb, '["Houseboat night","Watch tower swim","Niladri Lake","Barikka Tila sunset"]'::jsonb, '[]'::jsonb, 'haor', '["Houseboat stay","All meals","Local transfers","Guide"]'::jsonb, '["Personal expenses"]'::jsonb, '["Backpack (30–40 L)","Comfortable trekking shoes with grip","2–3 quick-dry T-shirts","Light jacket / rain poncho","Water bottle (1 L) & ORS","Personal medicines","Torch / headlamp","National ID card (mandatory for hill tracts)","Power bank","Sunscreen, cap & sunglasses"]'::jsonb, '[{"day":1,"title":"Board the houseboat","items":[{"time":"09:00 AM","text":"Tahirpur ghat, board the boat"},{"time":"01:00 PM","text":"Watch tower & swim"},{"time":"08:00 PM","text":"Night on the haor"}],"meals":"All meals","stay":"Houseboat","duration":"12h"},{"day":2,"title":"Niladri & return","items":[{"time":"08:00 AM","text":"Niladri Lake & Barikka Tila"},{"time":"04:00 PM","text":"Return to Sunamganj"}],"meals":"Breakfast, Lunch","duration":"10h"}]'::jsonb, '[{"id":"syl-ambarkhana","name":"Ambarkhana Point","detail":"Sylhet City","time":"07:30 AM","extraFee":0,"mapUrl":"https://maps.google.com/?q=Ambarkhana+Sylhet"},{"id":"dhaka-kalabagan","name":"Kalabagan Bus Stand","detail":"Mirpur Road, Dhaka","time":"11:00 PM (previous night)","extraFee":1100,"mapUrl":"https://maps.google.com/?q=Kalabagan+Bus+Stand+Dhaka"}]'::jsonb, '[{"question":"What is included in the package?","answer":"Transport from the pickup point, stay, meals as listed, local guide, permits and first aid. See the Amenities tab for the full list."},{"question":"Do I need previous tre