insert into public.testimonials (id, name, trip, rating, quote) values
  ('t1', 'Nusrat Jahan', 'Sajek Valley', 5, 'I had a wonderful experience with Ghuri Trails. The arrangements were well organized and the team was very friendly from start to finish.'),
  ('t2', 'Tanvir Ahmed', 'Keokradong Trek', 5, 'The trek leaders were super supportive. Sunrise from the summit was the best moment of my life so far!'),
  ('t3', 'Farhana Akter', 'Saint Martin''s Island', 4, 'Smooth ship booking, a lovely resort and the seafood BBQ night was amazing. Will travel again for sure.'),
  ('t4', 'Rakibul Hasan', 'Nafakhum Waterfall', 5, 'The best when it comes to planning trips and managing amazing experiences. Very safe and professional.'),
  ('t5', 'Sadia Islam', 'Sreemangal', 5, 'Perfect weekend trip with family. Kids loved Lawachara and the seven-layer tea!'),
  ('t6', 'Mahmudul Karim', 'Sundarbans', 5, 'The houseboat was clean, the food was delicious and we saw so many deer and crocodiles.'),
  ('t7', 'Ayesha Siddika', 'Tanguar Haor', 4, 'Sleeping on the haor under the stars was magical. Well planned and properly managed.'),
  ('t8', 'Imran Hossain', 'Khoiyachora Waterfall', 5, 'Great one-day trek from Chattogram. Guides knew every rock on the trail.'),
  ('t9', 'Shirin Sultana', 'Ratargul & Bichanakandi', 5, 'Everything was well planned. The boat ride inside Ratargul felt like a movie scene.'),
  ('t10', 'Arif Chowdhury', 'Kaptai Lake', 4, 'Relaxed, comfortable and great value. The lakeside resort was beautiful.'),
  ('t11', 'Mitu Rahman', 'Kuakata', 5, 'Seeing both sunrise and sunset on the same beach — thank you for this unforgettable trip!'),
  ('t12', 'Sabbir Hossain', 'Bagerhat Heritage', 5, 'Our guide explained the history of every mosque. A perfect day trip for history lovers.');
insert into public.faqs (id, question, answer, category, sort_order) values
  ('f1', 'Where is Ghuri Trails based?', 'Ghuri Trails is based in Dhaka and operates trips across Bangladesh, with departures from Dhaka, Chattogram and Sylhet.', 'General', 0),
  ('f2', 'Does Ghuri Trails operate across Bangladesh?', 'Yes. We run trips to the hill tracts, beaches, haors, tea gardens, mangrove forests and heritage sites all over the country.', 'General', 1),
  ('f3', 'What type of trips does Ghuri Trails offer?', 'Treks, weekend tours, family tours, honeymoon packages, campus tours, corporate outings and fully customized trips.', 'General', 2),
  ('f4', 'Do you organize trips from Chattogram and Sylhet?', 'Yes. Many of our trips have pickup points in Chattogram and Sylhet in addition to Dhaka.', 'General', 3),
  ('f5', 'Do you organize corporate and group trips?', 'Yes, we plan private group, corporate and student tours with custom dates and itineraries.', 'General', 4),
  ('f6', 'Do I need a National ID to travel?', 'Yes. For Bandarban, Rangamati and Khagrachari a NID or passport copy is mandatory for army check-posts. Students can use their student ID.', 'General', 5),
  ('f7', 'Are trips available all year round?', 'Most trips run all year. Saint Martin runs November–March and some treks pause in heavy monsoon for safety.', 'General', 6),
  ('f8', 'How can I book a trip with Ghuri Trails?', 'Open a package, choose a departure batch and the number of travellers, then submit the booking form. Our team will call you to confirm.', 'Booking', 7),
  ('f9', 'Can I book a trip for a group?', 'Yes. Select the number of travellers on the package page, or contact us for groups larger than 12 to get a group discount.', 'Booking', 8),
  ('f10', 'Can I join a trip alone?', 'Of course! Many travellers join solo and leave with new friends.', 'Booking', 9),
  ('f11', 'Can I request a customized itinerary?', 'Yes, contact us with your dates, destination and budget and we will design a plan for you.', 'Booking', 10),
  ('f12', 'Where can I find the complete trip details?', 'Every package page has the overview, day-by-day itinerary, route map, inclusions, things to carry and policies.', 'Booking', 11),
  ('f13', 'Is my booking confirmed immediately?', 'Your seats are reserved as soon as you submit. The booking is confirmed after our team calls you and the advance payment is received.', 'Booking', 12),
  ('f14', 'How do I pay?', 'We accept bKash, Nagad, Rocket and bank transfer. Payment details are shared by our team after the confirmation call.', 'Booking', 13),
  ('f15', 'Is safety taken care of during the trip?', 'Yes. Every group has trained leaders, a first-aid kit and local guides. We follow all army and forest department guidelines.', 'Safety', 14),
  ('f16', 'Are trek leaders or trip coordinators provided?', 'Yes, at least one leader for every 10 travellers, plus registered local guides on treks.', 'Safety', 15),
  ('f17', 'Are Ghuri Trails treks suitable for beginners?', 'Yes. Trips marked Beginner need no experience. Check the level badge on each package.', 'Safety', 16),
  ('f18', 'Is travel insurance included?', 'Basic accident coverage is included on treks. We recommend personal travel insurance for longer trips.', 'Safety', 17),
  ('f19', 'Is it safe for female travellers?', 'Yes. Our groups often have many female travellers, with female coordinators on request and separate rooms.', 'Safety', 18),
  ('f20', 'What should I carry for a trek?', 'Check the Amenities & Gear tab on each package. Good shoes, a rain cover, a torch and a water bottle are essential.', 'Gear', 19),
  ('f21', 'Can I rent trekking gear?', 'Yes, backpacks, trekking poles and rain ponchos can be rented. Mention it while booking.', 'Gear', 20),
  ('f22', 'Do I need special shoes?', 'Shoes with a good grip are a must for hill treks. Rubber sandals with straps work for stream crossings.', 'Gear', 21),
  ('f23', 'What is the cancellation policy?', 'Cancel 15+ days before departure for a full refund minus a ৳500 fee, 7–14 days for 50%, and no refund within 7 days.', 'Cancellation', 22),
  ('f24', 'What if the trip is cancelled due to weather?', 'If we cancel, you can choose a full refund or move to another batch free of charge.', 'Cancellation', 23),
  ('f25', 'Can I transfer my booking to someone else?', 'Yes, seat transfers are free up to 24 hours before departure.', 'Cancellation', 24),
  ('f26', 'Are cancellation charges applicable?', 'Charges depend on how early you cancel. See the Cancellation & Refund Policy page for details.', 'Cancellation', 25);
