insert into public.blog_posts (slug, title, excerpt, body, author, published_at, read_minutes, tags, image_url, scene) values
  ('best-time-to-visit-sajek-valley', 'Best Time to Visit Sajek Valley (Month-by-Month Guide)', 'Clouds in the monsoon, crystal skies in winter — here is when to plan your Sajek trip and what to expect each season.', '["Sajek Valley changes its personality with every season. From June to September the valley below fills with clouds every morning, giving the famous “sea of clouds” view from Konglak hill.","From October to February the weather is cool and dry, the sky is clear and you can see the hills of Mizoram far away. This is the most comfortable time for families.","March to May is hot and hazy, but the cottages are cheaper and the roads are quiet. Whatever month you choose, book cottages early on weekends and holidays."]'::jsonb, 'Team Ghuri Trails', '2026-08-12', 6, '["Sajek","Guide"]'::jsonb, null, 'hills'),
  ('first-trek-in-bandarban-checklist', 'Your First Trek in Bandarban: The Complete Checklist', 'NID copies, shoes with grip, ORS and a headlamp — everything a first-time trekker needs for the hill tracts.', '["Bandarban is the trekking capital of Bangladesh. Before you go, make photocopies of your National ID — the army camps check them at every entry point.","Shoes are the most important gear: choose a pair with deep grip, or rubber sandals with straps for the jhiri trails. Carry ORS, a small first-aid pouch and a headlamp.","Finally, respect the local Bawm, Marma and Mro communities: ask before taking photos and never leave plastic on the trail."]'::jsonb, 'Team Ghuri Trails', '2026-07-28', 8, '["Bandarban","Trekking","Gear"]'::jsonb, null, 'waterfall'),
  ('saint-martin-travel-guide', 'Saint Martin''s Island Travel Guide 2026–27', 'Ship schedules, where to stay, Chhera Dwip timings and the new visitor rules explained.', '["Ships to Saint Martin usually run from November to March from Cox’s Bazar and Teknaf, subject to permission and weather.","Stay on the west side for sunsets or on the north beach to be close to the jetty. Walk to Chhera Dwip only during low tide and return before the water rises.","Coral is fragile: do not collect stones or shells, and keep the island plastic-free."]'::jsonb, 'Team Ghuri Trails', '2026-09-02', 7, '["Saint Martin","Beach"]'::jsonb, null, 'island'),
  ('sylhet-in-two-days', 'Sylhet in Two Days: Ratargul, Bichanakandi & Jaflong', 'A tight but relaxed plan to see the best of Sylhet in a single weekend.', '["Day one: start early for Ratargul swamp forest and take a small boat through the flooded trees, then head to Jaflong for the evening.","Day two: drive to Hadarpar and take a boat to Bichanakandi. The water is coldest and clearest in the morning.","Eat at the local restaurants in Sylhet city — try shatkora beef and the famous seven-layer tea on the way back via Sreemangal."]'::jsonb, 'Team Ghuri Trails', '2026-06-18', 5, '["Sylhet","Itinerary"]'::jsonb, null, 'forest');
